// Arquivo completo e redesenhado para: src/components/HomePage.js

import React from 'react';

// A função agora recebe 'onNavigateToSignup' para o botão de cadastro
function HomePage({ onNavigateToLogin, onNavigateToSignup, isLoggedIn, userData, onLogout, onNavigateToDashboard }) {
    const handlePlaceholderClick = (feature) => {
        alert(`A funcionalidade "${feature}" será implementada em breve!`);
    };

    // --- NOVOS DADOS PARA AS SEÇÕES ---
    const differentials = [
        { icon: '🏆', title: "Qualidade Superior", description: "Equipamentos de ponta e profissionais qualificados para garantir o melhor para seu pet." },
        { icon: '❤️', title: "Cuidado com Amor", description: "Tratamos cada pet com o carinho e a dedicação que ele merece, como se fosse nosso." },
        { icon: '📅', title: "Conveniência Total", description: "Agende serviços, acompanhe históricos e gerencie tudo online, de forma fácil e rápida." }
    ];

    const services = [
        { icon: '🩺', title: "Consultas Veterinárias", description: "Check-ups, diagnósticos e tratamentos com uma equipe de especialistas." },
        { icon: '🛁', title: "Banho e Tosa", description: "Higiene e estética com produtos de alta qualidade para o bem-estar do seu amigo." },
        { icon: '💉', title: "Vacinas e Imunização", description: "Mantenha a saúde do seu pet em dia com nosso programa completo de vacinação." },
        { icon: '🛍️', title: "Pet Shop Completo", description: "Rações, brinquedos, acessórios e tudo que seu pet precisa para ser feliz." }
    ];

    const testimonials = [
        { name: "Ana P.", pet: "Toby, Golden Retriever", text: "O atendimento na PetLife é incrível! O Dr. Ricardo foi super atencioso com o Toby e o banho ficou impecável. Recomendo de olhos fechados!" },
        { name: "Carlos S.", pet: "Mimi, Gata SRD", text: "Levei a Mimi para vacinar e a equipe foi muito paciente e carinhosa. O sistema de agendamento online facilitou muito minha vida." },
        { name: "Juliana M.", pet: "Fred, Bulldog Francês", text: "A melhor pet shop da cidade! Encontro tudo que preciso para o Fred, e a equipe está sempre pronta para ajudar com as melhores indicações." }
    ];

    return (
        <>
            {/* --- SEÇÃO DE HERÓI REDESENHADA --- */}
            <section className="hero-v2">
                <div className="hero-content">
                    <h1 className="animate-fade-in-up">
                        {isLoggedIn ? `Olá, ${userData?.nome ? userData.nome.split(' ')[0] : 'Usuário'}!` : "Cuidar de quem amamos é um ato de amor."}
                    </h1>
                    <p className="animate-fade-in-up">
                        {isLoggedIn ?
                        "Seu companheiro merece o melhor. Explore nossos serviços e agende o próximo cuidado." :
                        "Na PetLife, oferecemos um cuidado completo e humanizado para seu pet. Saúde, bem-estar e felicidade em um só lugar."}
                    </p>
                    <div className="hero-buttons">
                        <button className="btn btn-primary hover-lift" onClick={() => handlePlaceholderClick('Agendamento')}>📅 Agendar um Serviço</button>
                        {!isLoggedIn && <button className="btn btn-secondary hover-lift" onClick={onNavigateToSignup}>🐾 Quero ser Cliente</button>}
                    </div>
                </div>
                <div className="hero-image-container">
                    {/* Você pode substituir esta div por uma imagem real */}
                    <div className="hero-image-placeholder"></div>
                </div>
            </section>

            {/* --- NOVA SEÇÃO: NOSSOS DIFERENCIAIS --- */}
            <section className="section bg-light">
                <div className="container text-center">
                    <h2 className="section-title">Por que escolher a PetLife?</h2>
                    <p className="section-description">Entendemos que seu pet é parte da família. Por isso, nosso compromisso vai além do serviço.</p>
                    <div className="grid-3">
                        {differentials.map((item, index) => (
                            <div key={index} className="feature-card animate-fade-in-up" style={{ animationDelay: `${index * 0.1}s` }}>
                                <div className="feature-icon">{item.icon}</div>
                                <h3>{item.title}</h3>
                                <p>{item.description}</p>
                            </div>
                        ))}
                    </div>
                </div>
            </section>

            {/* --- SEÇÃO DE SERVIÇOS (MANTIDA E ESTILIZADA) --- */}
            <section className="section">
                <div className="container text-center">
                    <h2 className="section-title">Nossos Serviços</h2>
                    <p className="section-description">Uma gama completa de soluções para garantir a saúde e a felicidade do seu companheiro.</p>
                    <div className="services-grid">
                        {services.map((service, index) =>
                            <div key={index} className="service-card hover-lift animate-fade-in-up" style={{ animationDelay: `${index * 0.1}s` }}>
                                <div className="icon">{service.icon}</div>
                                <h3>{service.title}</h3>
                                <p>{service.description}</p>
                            </div>
                        )}
                    </div>
                </div>
            </section>

            {/* --- NOVA SEÇÃO: DEPOIMENTOS --- */}
            <section className="section bg-light">
                <div className="container text-center">
                    <h2 className="section-title">O que nossos clientes dizem</h2>
                    <p className="section-description">A confiança de quem já conhece nosso trabalho é nossa maior recompensa.</p>
                    <div className="testimonials-grid">
                        {testimonials.map((testimonial, index) => (
                            <div key={index} className="testimonial-card animate-fade-in-up" style={{ animationDelay: `${index * 0.1}s` }}>
                                <p className="testimonial-text">"{testimonial.text}"</p>
                                <div className="testimonial-author">
                                    <strong>{testimonial.name}</strong>
                                    <span>, tutor(a) de {testimonial.pet}</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </section>

            {/* --- SEÇÃO CTA (CALL-TO-ACTION) FINAL --- */}
            <section className="cta-v2">
                <div className="container text-center">
                    <h2>Pronto para oferecer o melhor ao seu pet?</h2>
                    <p>Junte-se à família PetLife e descubra uma nova forma de cuidar de quem você ama.</p>
                    <div className="cta-buttons">
                        <button className="btn btn-primary btn-lg hover-lift" onClick={() => handlePlaceholderClick('Agendamento')}>Agendar Agora</button>
                        {!isLoggedIn && <button className="btn btn-outline-white btn-lg hover-lift" onClick={onNavigateToSignup}>Criar Minha Conta</button>}
                    </div>
                </div>
            </section>
        </>
    );
}
export default HomePage;
